export const ALBUM_LIMIT=12;
export function validGamePhoto(photo){return !!photo&&typeof photo.id==='string'&&photo.id.length<=100&&typeof photo.title==='string'&&photo.title.length>0&&photo.title.length<=80&&Number.isFinite(photo.capturedAt)&&photo.capturedAt>0&&Number.isFinite(new Date(photo.capturedAt).getTime())&&photo.blob instanceof Blob&&photo.blob.type==='image/jpeg'&&photo.blob.size>0&&photo.blob.size<=6*1024*1024&&Number.isInteger(photo.width)&&photo.width>0&&photo.width<=1600&&Number.isInteger(photo.height)&&photo.height>0&&photo.height<=1600}
export function createGameAlbum(indexedDB,scope='player'){
 if(indexedDB===undefined)try{indexedDB=globalThis.indexedDB}catch{}
 let opening;
 function open(){if(opening)return opening;opening=new Promise((resolve,reject)=>{if(!indexedDB){reject(Error('Storan album tidak tersedia. Anda masih boleh memuat turun foto.'));return}let abandoned=false;const request=indexedDB.open(scope==='superadmin'?'jelajah-labuan-superadmin-album-v1':'jelajah-labuan-album-v1',1);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains('photos'))db.createObjectStore('photos',{keyPath:'id'})};request.onerror=()=>reject(Error('Album tidak dapat dibuka. Muat turun foto sebagai sandaran.'));request.onblocked=()=>{abandoned=true;reject(Error('Tutup tab lama permainan sebelum membuka album.'))};request.onsuccess=()=>{const db=request.result;if(abandoned){db.close();return}db.onversionchange=()=>{db.close();opening=null};resolve(db)}}).catch(error=>{opening=null;throw error});return opening}
 return {async list(){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readonly'),request=tx.objectStore('photos').getAll();tx.oncomplete=()=>resolve(request.result.filter(validGamePhoto).sort((a,b)=>b.capturedAt-a.capturedAt));tx.onabort=tx.onerror=()=>reject(Error('Album tidak dapat dibaca.'))})},async save(photo){if(!validGamePhoto(photo))throw Error('Data foto tidak sah.');const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite'),store=tx.objectStore('photos');let reason;const find=store.get(photo.id);find.onsuccess=()=>{if(find.result){reason=Error('Foto ini sudah disimpan.');tx.abort();return}const count=store.count();count.onsuccess=()=>{if(count.result>=ALBUM_LIMIT){reason=Error('Album penuh (12 foto). Padam satu foto atau muat turun gambar ini.');tx.abort();return}store.add(photo)}};tx.oncomplete=()=>resolve(photo);tx.onabort=tx.onerror=()=>reject(reason||Error('Foto tidak dapat disimpan. Storan mungkin penuh; muat turun foto ini.'))})},async remove(id){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').delete(id);tx.oncomplete=()=>resolve();tx.onabort=tx.onerror=()=>reject(Error('Foto tidak dapat dipadam.'))})},async close(){const db=opening?await opening:null;db?.close();opening=null}};
}
